def _non_space(text: str, idx: int) -> bool:
    """True if ``text[idx]`` exists and is not a whitespace character."""
    return idx >= 0 and not text[idx].isspace()


def _split_code(text: str) -> list[tuple[bool, str]]:
    """Split *text* into ``(is_code_span, content)`` segments.

    Code spans are paired left to right: each backtick pairs with the
    next backtick.  A backtick with no partner is kept as literal text.
    """
    segments: list[tuple[bool, str]] = []
    i = 0
    while True:
        j = text.find("`", i)
        if j == -1:
            segments.append((False, text[i:]))
            break
        if j > i:
            segments.append((False, text[i:j]))
        k = text.find("`", j + 1)
        if k == -1:
            # Unpaired backtick: it and the rest are plain text.
            segments.append((False, text[j:]))
            break
        segments.append((True, text[j + 1:k]))
        i = k + 1
    return segments


def _find_close(text: str, start: int, double: bool) -> int:
    """Index of the first valid closing marker at or after *start*, else -1.

    A closing marker is ``*`` (or ``**`` when *double*) preceded by a
    non-space character.
    """
    n = len(text)
    j = start
    while j < n:
        if text[j] == "*":
            if double:
                if (
                    j + 1 < n
                    and text[j + 1] == "*"
                    and _non_space(text, j - 1)
                ):
                    return j
            elif _non_space(text, j - 1):
                return j
        j += 1
    return -1


def _emph(text: str) -> str:
    """Format ``**bold**`` and ``*italic*`` markers in *text*.

    An opening ``*`` or ``**`` must be followed by a non-space character
    and the matching closing marker must be preceded by one; markers
    without a partner are left as literal text.
    """
    out: list[str] = []
    i = 0
    n = len(text)
    while i < n:
        if text[i] == "*" and i + 1 < n and text[i + 1] == "*":
            if i + 2 < n and not text[i + 2].isspace():
                j = _find_close(text, i + 2, True)
                if j != -1:
                    out.append(
                        "<strong>" + _emph(text[i + 2:j]) + "</strong>"
                    )
                    i = j + 2
                    continue
            # No valid bold pair: leave the star literal and move on.
            out.append("*")
            i += 1
            continue
        if text[i] == "*" and i + 1 < n and not text[i + 1].isspace():
            j = _find_close(text, i + 1, False)
            if j != -1:
                out.append("<em>" + _emph(text[i + 1:j]) + "</em>")
                i = j + 1
                continue
        out.append(_escape(text[i]))
        i += 1
    return "".join(out)


def _inline(text: str) -> str:
    """Render the inline formatting of *text* as HTML.

    Code spans are split off first; their content is escaped but never
    formatted.  The remaining segments are scanned for emphasis and all
    plain characters are escaped.
    """
    out: list[str] = []
    for is_code, content in _split_code(text):
        if is_code:
            out.append(f"<code>{_escape(content)}</code>")
        else:
            out.append(_emph(content))
    return "".join(out)


